-- PREVIEW ONLY. Additive attendance/payroll persistence; no payment or ledger posting.
CREATE TABLE "attendance_sessions" ("id" BIGSERIAL PRIMARY KEY,"branch_id" BIGINT NOT NULL,"employee_id" UUID NOT NULL,"opened_at" TIMESTAMP(3) NOT NULL,"closed_at" TIMESTAMP(3),"requires_correction" BOOLEAN NOT NULL DEFAULT false,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("branch_id") REFERENCES "branches"("id") ON DELETE RESTRICT,FOREIGN KEY ("employee_id") REFERENCES "users"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "attendance_one_open_session" ON "attendance_sessions"("employee_id") WHERE "closed_at" IS NULL;
CREATE TABLE "attendance_events" ("id" BIGSERIAL PRIMARY KEY,"session_id" BIGINT NOT NULL,"event_type" VARCHAR(20) NOT NULL,"occurred_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"idempotency_key" VARCHAR(100) NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "attendance_event_type" CHECK ("event_type" IN ('clock_in','clock_out','break_start','break_end')),FOREIGN KEY ("session_id") REFERENCES "attendance_sessions"("id") ON DELETE RESTRICT,UNIQUE("session_id","idempotency_key"));
CREATE TABLE "payroll_policies" ("id" BIGSERIAL PRIMARY KEY,"branch_id" BIGINT,"effective_from" DATE NOT NULL,"daily_hours" SMALLINT NOT NULL DEFAULT 8,"grace_minutes" SMALLINT NOT NULL DEFAULT 30,"overtime_multiplier" NUMERIC(8,4) NOT NULL DEFAULT 1.5,"currency" VARCHAR(3) NOT NULL DEFAULT 'EGP',"preview_only" BOOLEAN NOT NULL DEFAULT true,"created_by" UUID NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("branch_id") REFERENCES "branches"("id") ON DELETE RESTRICT,FOREIGN KEY ("created_by") REFERENCES "users"("id") ON DELETE RESTRICT);
CREATE TABLE "payroll_periods" ("id" BIGSERIAL PRIMARY KEY,"branch_id" BIGINT NOT NULL,"starts_on" DATE NOT NULL,"ends_on" DATE NOT NULL,"timezone" VARCHAR(50) NOT NULL,"status" VARCHAR(20) NOT NULL DEFAULT 'draft',"policy_id" BIGINT NOT NULL,"created_by" UUID NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "payroll_period_dates" CHECK ("ends_on" >= "starts_on"),FOREIGN KEY ("branch_id") REFERENCES "branches"("id") ON DELETE RESTRICT,FOREIGN KEY ("policy_id") REFERENCES "payroll_policies"("id") ON DELETE RESTRICT,FOREIGN KEY ("created_by") REFERENCES "users"("id") ON DELETE RESTRICT,UNIQUE("branch_id","starts_on","ends_on"));
CREATE TABLE "payroll_lines" ("id" BIGSERIAL PRIMARY KEY,"payroll_period_id" BIGINT NOT NULL,"employee_id" UUID NOT NULL,"compensation_snapshot" JSONB NOT NULL,"attendance_snapshot" JSONB NOT NULL,"policy_snapshot" JSONB NOT NULL,"gross_estimate_cents" BIGINT NOT NULL,"deduction_estimate_cents" BIGINT NOT NULL DEFAULT 0,"advance_recovery_estimate_cents" BIGINT NOT NULL DEFAULT 0,"net_estimate_cents" BIGINT NOT NULL,"warnings" JSONB NOT NULL DEFAULT '[]',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("payroll_period_id") REFERENCES "payroll_periods"("id") ON DELETE RESTRICT,FOREIGN KEY ("employee_id") REFERENCES "users"("id") ON DELETE RESTRICT,UNIQUE("payroll_period_id","employee_id"));
ALTER TABLE "attendance_sessions" ENABLE ROW LEVEL SECURITY; ALTER TABLE "attendance_events" ENABLE ROW LEVEL SECURITY; ALTER TABLE "payroll_policies" ENABLE ROW LEVEL SECURITY; ALTER TABLE "payroll_periods" ENABLE ROW LEVEL SECURITY; ALTER TABLE "payroll_lines" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE "attendance_sessions","attendance_events","payroll_policies","payroll_periods","payroll_lines" FROM PUBLIC, anon, authenticated;
